WITH base AS (SELECT id, channel, ends_on, CASE WHEN promo_code IN ('WELCOME5', 'SPRING10') THEN 'Tier 1' ELSE 'Other' END AS promo_code_group FROM promotions WHERE ends_on > DATE '2024-04-14' AND ends_on <= '2024-10-01'), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY ends_on, id) AS dedup_rank FROM base) t WHERE dedup_rank = 1), metrics AS (SELECT id, channel, ends_on, promo_code_group, dedup_rank, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY ends_on DESC, id) AS event_seq, ROW_NUMBER() OVER (ORDER BY ends_on, id) AS event_seq_2 FROM ranked), deduped AS (SELECT * FROM metrics QUALIFY ROW_NUMBER() OVER (PARTITION BY channel ORDER BY ends_on DESC, id) = 1), enriched AS (SELECT id, channel, ends_on, promo_code_group, dedup_rank, event_seq, event_seq_2, FIRST_VALUE(event_seq_2) IGNORE NULLS OVER (ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_event_seq_2, LAST_VALUE(event_seq, TRUE) OVER (PARTITION BY channel ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_event_seq, FIRST_VALUE(event_seq, TRUE) OVER (PARTITION BY channel ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_event_seq, SUM(event_seq_2) OVER (ORDER BY dedup_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_event_seq_2, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY channel ORDER BY dedup_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM deduped), ranked_promotions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY cumulative_event_seq_2 DESC NULLS LAST, id) AS dedup_rank_2 FROM enriched) x WHERE dedup_rank_2 = 1), valid AS (SELECT *, dedup_rank * last_known_event_seq AS dedup_rank_times_last_known_event_seq FROM ranked_promotions WHERE ends_on > DATE '2023-08-31' AND channel IS NOT NULL), grouped AS (SELECT CASE WHEN event_seq >= 9 THEN 'LARGE' ELSE 'SMALL' END AS event_seq_tier, CASE WHEN first_known_event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS first_known_event_seq_tier, channel, PERCENTILE_APPROX(event_seq_2, 0.95) AS event_seq_2_p95, COUNT(*) AS num_rows, ROUND(AVG(first_known_event_seq_2), 2) AS avg_first_known_event_seq_2, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, COUNT(*) FILTER (WHERE channel = 'partner') AS partner_rows FROM valid GROUP BY CUBE (CASE WHEN event_seq >= 9 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN first_known_event_seq >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, channel)) SELECT event_seq_tier, first_known_event_seq_tier, channel, event_seq_2_p95, avg_first_known_event_seq_2, partner_rows FROM grouped ORDER BY partner_rows
